+/**
+ * @brief 向 TH USART1 注入指定载荷长度的 0x17 急停控制帧并触发协议轮询
+ * @param dst   目标节点地址（MINIMC_NODE_TH 或 MINIMC_NODE_BROADCAST）
+ * @param flags 帧头标志位
+ * @param pay   载荷缓冲区指针（plen 为 0 时可传 NULL）
+ * @param plen  载荷字节数
+ */
+static void send_th_estop_frame(uint8_t dst, uint8_t flags, const uint8_t *pay, uint16_t plen)
+{
+    static uint16_t s_estop_seq = 0x0200U;
+    const uint16_t seq = s_estop_seq++;
+    uint8_t frame[32];
+    require_true(plen <= 16U, "estop test plen <= 16");
+    frame[0] = MINIMC_SOF_1;
+    frame[1] = MINIMC_SOF_2;
+    frame[2] = MINIMC_NODE_AP;
+    frame[3] = dst;
+    frame[4] = flags;
+    frame[5] = MINIMC_CMD_EMERGENCY_STOP;
+    frame[6] = 3U;
+    frame[7] = MINIMC_ROUTE_IS_ROUTED;
+    frame[8] = (uint8_t)(seq & 0xFFU);
+    frame[9] = (uint8_t)((seq >> 8U) & 0xFFU);
+    frame[10] = (uint8_t)(plen & 0xFFU);
+    frame[11] = (uint8_t)((plen >> 8U) & 0xFFU);
+    if ((plen > 0U) && (pay != NULL))
+    {
+        memcpy(&frame[12], pay, plen);
+    }
+    const uint16_t crc = minimc_crc16(frame, (uint16_t)(12U + plen));
+    frame[12U + plen] = (uint8_t)(crc & 0xFFU);
+    frame[13U + plen] = (uint8_t)((crc >> 8U) & 0xFFU);
+    const uint16_t total = (uint16_t)(14U + plen);
+    for (uint16_t i = 0U; i < total; ++i)
+    {
+        usart1_rx_buffer[s_usart1_rx_write_pos] = frame[i];
+        s_usart1_rx_write_pos = (uint16_t)((s_usart1_rx_write_pos + 1U) % USART1_RXBUFF_SIZE);
+    }
+    s_usart1_last_tx_len = 0U;
+    minimc_proto_poll();
+}
+
+/**
+ * @brief 验证 TH-ESTOP-01：单播 0x17 锁存(0x01)与解除(0x00)均回 18B(4B ACK)，且解除不误触发关断/M112
+ */
+static void test_th_estop_0x17_latch_and_release(void)
+{
+    minimc_proto_init();
+    thermistor_set_target_deci_c(2150);
+    load_filament_Flag = 1;
+    s_th_quickstop_count = 0U;
+    const uint32_t enq_0 = th_control_get_enqueued_count();
+
+    /* 1. 0x17 [0x01] 急停锁存：返回 18B (4B CMD_ACK) + quickStop + 清零目标温度 + 入队 M112 */
+    const uint8_t mode_latch = 0x01U;
+    send_th_estop_frame(MINIMC_NODE_TH, 0x05U, &mode_latch, 1U);
+    const uint16_t ack1_crc = (uint16_t)s_usart1_last_tx[16] | ((uint16_t)s_usart1_last_tx[17] << 8U);
+    require_true(s_usart1_last_tx_len == 18U && s_usart1_last_tx[5] == MINIMC_CMD_ACK, "0x17 [0x01] -> 18B CMD_ACK");
+    require_true(s_usart1_last_tx[10] == 4U && s_usart1_last_tx[14] == 0U && s_usart1_last_tx[15] == 0U, "4B ACK reserved=0");
+    require_true(minimc_crc16(s_usart1_last_tx, 16U) == ack1_crc, "0x17 [0x01] ACK CRC16 valid");
+    require_true(s_th_quickstop_count == 1U && thermistor_get_target_deci_c() == 0 && load_filament_Flag == 0, "latch stops & zeroes temp");
+    require_true(th_control_get_enqueued_count() == (enq_0 + 1U) && strcmp(th_control_get_last_gcode(), "M112") == 0, "latch enqueues M112");
+    th_control_poll_once();
+
+    /* 2. 0x17 [0x00] 解除急停：返回 18B (4B CMD_ACK)，绝不调用 quickStop、不清零目标温度、不入队 M112 */
+    thermistor_set_target_deci_c(2050);
+    load_filament_Flag = 1;
+    s_th_quickstop_count = 0U;
+    const uint32_t enq_1 = th_control_get_enqueued_count();
+    const uint8_t mode_release = 0x00U;
+    send_th_estop_frame(MINIMC_NODE_TH, 0x05U, &mode_release, 1U);
+    const uint16_t ack0_crc = (uint16_t)s_usart1_last_tx[16] | ((uint16_t)s_usart1_last_tx[17] << 8U);
+    require_true(s_usart1_last_tx_len == 18U && s_usart1_last_tx[5] == MINIMC_CMD_ACK, "0x17 [0x00] -> 18B CMD_ACK");
+    require_true(s_usart1_last_tx[10] == 4U && s_usart1_last_tx[14] == 0U && s_usart1_last_tx[15] == 0U, "0x17 [0x00] 4B ACK reserved=0");
+    require_true(minimc_crc16(s_usart1_last_tx, 16U) == ack0_crc, "0x17 [0x00] ACK CRC16 valid");
+    require_true(s_th_quickstop_count == 0U && thermistor_get_target_deci_c() == 2050 && load_filament_Flag == 1, "release keeps temp & motor state");
+    require_true(th_control_get_enqueued_count() == enq_1, "release must NOT enqueue M112");
+    thermistor_set_target_deci_c(0);
+    load_filament_Flag = 0;
+}
+
+/**
+ * @brief 验证 TH-ESTOP-01 负例与广播：0x17 非法模式(0x02)->NACK 0x03、plen>1->NACK 0x02、广播及免应答返回 0B
+ */
+static void test_th_estop_0x17_nack_and_bcast(void)
+{
+    minimc_proto_init();
+    thermistor_set_target_deci_c(1900);
+    const uint32_t enq_init = th_control_get_enqueued_count();
+
+    /* 1. 非法 stop_mode=0x02：单播回 NACK 0x03 且不误触发急停；广播静默返回 0B */
+    const uint8_t bad_mode = 0x02U;
+    send_th_estop_frame(MINIMC_NODE_TH, 0x05U, &bad_mode, 1U);
+    require_true(s_usart1_last_tx_len == 17U && s_usart1_last_tx[5] == MINIMC_CMD_NACK && s_usart1_last_tx[12] == 0x03U, "stop_mode=2 -> NACK 0x03");
+    require_true(thermistor_get_target_deci_c() == 1900 && th_control_get_enqueued_count() == enq_init, "bad mode has no side effects");
+    send_th_estop_frame(MINIMC_NODE_BROADCAST, 0x05U, &bad_mode, 1U);
+    require_true(s_usart1_last_tx_len == 0U, "broadcast bad mode -> 0B");
+
+    /* 2. 超长载荷 plen=2 (>1)：单播回 NACK 0x02；广播静默返回 0B */
+    const uint8_t over_pay[2] = { 0x01U, 0x00U };
+    send_th_estop_frame(MINIMC_NODE_TH, 0x05U, over_pay, 2U);
+    require_true(s_usart1_last_tx_len == 17U && s_usart1_last_tx[5] == MINIMC_CMD_NACK && s_usart1_last_tx[12] == 0x02U, "plen=2 -> NACK 0x02");
+    send_th_estop_frame(MINIMC_NODE_BROADCAST, 0x05U, over_pay, 2U);
+    require_true(s_usart1_last_tx_len == 0U, "broadcast plen=2 -> 0B");
+
+    /* 3. 广播 dst_id=0xFF 带 [0x01]/[0x00] 及单播免应答：均返回 0B 无应答 */
+    const uint8_t mode_latch = 0x01U;
+    const uint8_t mode_release = 0x00U;
+    send_th_estop_frame(MINIMC_NODE_BROADCAST, 0x15U, &mode_latch, 1U);
+    require_true(s_usart1_last_tx_len == 0U && thermistor_get_target_deci_c() == 0, "broadcast [0x01] latches without ACK");
+    th_control_poll_once();
+    send_th_estop_frame(MINIMC_NODE_BROADCAST, 0x15U, &mode_release, 1U);
+    require_true(s_usart1_last_tx_len == 0U, "broadcast [0x00] -> 0B");
+    send_th_estop_frame(MINIMC_NODE_TH, MINIMC_FLAG_PROTO_V2, &mode_release, 1U);
+    require_true(s_usart1_last_tx_len == 0U, "unicast without WANTS_ACK -> 0B");
+}
+
