+AisocOtaGateVerdict check_ota_scan_gate(bool has_conn, const AisocOtaStatus& st) {
+    if (!has_conn) return AisocOtaGateVerdict::DISCONNECTED;
+    // 仅拦截在途活跃任务；MC 待恢复模式 (!st.active && st.maintenance) 必须允许扫描恢复包。
