+}
+
+AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
+                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
+    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
+    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
+    const bool mc_recovery = (!st.active) && (st.maintenance || snap.mc.is_boot_mode ||
+                                              st.error == "RESTORE_MC_BEFORE_TH");
+    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
+    const bool mc_ready = ((mask & 1U) == 0U) || (st.mc.valid && !st.mc.sha256.empty());
+    const bool th_ready = ((mask & 2U) == 0U) || (st.th.valid && !st.th.sha256.empty());
+    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
+    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
+    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
+    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
+    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
+    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
+    return AisocOtaGateVerdict::ALLOW;
+}
