+def _read_default_language(default_settings: Path) -> str:
+    """读取只读模板 settings.json 中的默认语言代码；缺失或异常时返回空串。"""
+    if not default_settings.is_file():
+        return ''
+    try:
+        doc = json.loads(default_settings.read_text(encoding='utf-8'))
+    except (OSError, ValueError):
+        return ''
+    lang = doc.get('language', '') if isinstance(doc, dict) else ''
+    return lang if isinstance(lang, str) else ''
+
+
+def migrate_default_language_once(data: dict, default_lang: str) -> bool:
+    """对尚未标记迁移的存量英文或空语言配置执行一次性默认中文迁移。
+
+    参数:
+        data: 已加载的可写配置字典，原地更新语言与一次性迁移标记。
+        default_lang: 只读包内 `config/settings.json` 声明的默认语言代码。
+    返回:
+        bool: 若本次写入了迁移标记或更新了语言返回 True，无需修改返回 False。
+    """
+    if not isinstance(data, dict) or default_lang != 'zh':
+        return False
+    if 'c308l_default_lang_migrated' in data:
+        return False
+    # 仅在首次升级且原语言为空或存量默认英文时切为中文，后续用户手动切回英文不再覆盖。
+    cur_lang = data.get('language', '')
+    if cur_lang in ('', 'en', None):
+        data['language'] = 'zh'
+    data['c308l_default_lang_migrated'] = 1
+    return True
+
+
+def _panel_backup_candidates(panel_config: Path) -> list:
+    """收集面板首选状态目录与 HOME 回退目录下的全部滚动备份候选路径。"""
+    dirs = []
+    state_env = os.environ.get('HELIX_STATE_DIR', '').strip()
+    if state_env:
+        dirs.append(Path(state_env))
+    if os.environ.get('PRINTER_SOC_ROOT', '').strip():
+        dirs.append(resolve_root_path('/var/lib/helixscreen'))
+    elif len(panel_config.parents) >= 4 and panel_config.parts[-3:] == ('printer-soc', 'helix', 'config'):
+        dirs.append(panel_config.parents[3] / 'var/lib/helixscreen')
+    elif not str(panel_config).startswith('/tmp/'):
+        dirs.append(Path('/var/lib/helixscreen'))
+    dirs.append(panel_config.parent / '.helixscreen')
+    seen, candidates = set(), []
+    for base in dirs:
+        for name in ('settings.json.backup', 'helixconfig.json.backup'):
+            candidate = base / name
+            key = str(candidate)
+            if key not in seen:
+                seen.add(key)
+                candidates.append(candidate)
+    return candidates
+
+
+def sync_panel_backup_language(panel_config: Path, default_lang: str) -> None:
+    """同步迁移 `/var/lib/helixscreen` 与 `$HOME/.helixscreen` 全部滚动备份中的存量默认语言。
