 49	/** @brief 格式化真实 DDS OTA 阶段、校验策略、实测进度与重启核验提示（严禁前端假进度）。 */
 50	static std::string format_ota_phase(const helix::aisoc::AisocOtaStatus& st) {
 51	    if (st.last_rpc_code < 0) {
 52	        if (st.last_rpc_code == -5 || st.error == "BACKEND_BUSY") {
 53	            return "状态: 后台已锁定 (BUSY)";
 54	        }
 55	        if (st.error == "RPC_DISCONNECTED") {
 56	            return "状态: 本地服务未连接（请检查后台服务后重试）";
 57	        }
 58	        const std::string rpc_err = st.error.empty() ? std::string("OTA_COMMAND_REJECTED") : st.error;
 59	        return "升级失败: " + rpc_err + "（请核对设备在线状态与故障原因后重扫重试）";
 60	    }
 61	    if (st.error == "BACKEND_BUSY") {
 62	        return "状态: 后台已锁定 (BUSY)";
 63	    }
 64	    if (st.phase == "IDLE" && st.error == "RESTORE_MC_BEFORE_TH") {
 65	        return "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC";
 66	    }
 67	    if (st.phase == "IDLE" && st.error.empty()) {
 68	        return "等待扫描本地固件（请点击“扫描固定目录固件”检查 /run/printer-soc/firmware/）";
 69	    }
 70	    if (st.phase == "SUCCEEDED") {
 71	        if (st.reboot_verified) {
 72	            return "100% 升级完成，已回 App 且核验通过（可切回“关于”页复查版本）";
 73	        }
 74	        return "传输已提交，等待重启回 App(Bit31=0) 并核验版本与 boot_id...";
 75	    }
 76	    if (st.phase == "READY") {
 77	        // 按后端真实上报的编译期 policy 展示对应通过提示，消除硬编码验签误导。
 78	        if (st.policy == "signature-required") {
 79	            return "固件包签名与完整性校验通过，请确认目标与安全开关后开始升级";
 80	        }
 81	        return "固件包完整性校验通过，请确认目标与安全开关后开始升级";
 82	    }
 83	    if (st.phase == "FAILED" || (st.phase == "IDLE" && !st.error.empty())) {
 84	        if (st.error == "PACKAGE_MISSING") {
 85	            if (st.mc.valid || st.th.valid) {
 86	                return "已找到单板可升级固件包，缺失节点请放入固件后重扫或取消选择该板";
 87	            }
 88	            return "固定目录未找到可升级固件包，请放入 fw_th.bin / fw_mc.bin 后重新扫描";
 89	        }
 90	        if (st.error == "PACKAGE_INVALID_OR_CHANGED" || st.error == "PACKAGE_SIGNATURE_INVALID") {
 91	            return "固件包校验未通过，请核对节点提示并替换有效包后重新扫描";
 92	        }
 93	        const std::string err = st.error.empty() ? std::string("UNKNOWN") : st.error;
 94	        return "升级失败: " + err + "（请核对设备在线状态与故障原因后重扫重试）";
 95	    }
 96	    char buf[192] = {};
 97	    std::snprintf(buf, sizeof(buf), "升级进行中请勿断电：阶段 %s (%u%%)", st.phase.c_str(), st.progress_pct);
 98	    return std::string(buf);
 99	}
100	#endif
