188	void OtaLocalOverlay::sync_from_backend() {
189	#ifdef HELIX_ENABLE_AISOC
190	    auto* conn = helix::aisoc::active_aisoc_connection();
191	    if (!conn || !subjects_initialized_) return;
192	    const auto st = conn->ota_status();
193	    const auto snap = conn->snapshot();
194	    // RPC 刚受理但尚未收到新 task 首个 DDS 事件（event_id==0）时跳过旧残影覆盖，等待真实 DDS 状态。
195	    if (!st.task_id.empty() && st.event_id == 0U && st.last_rpc_code == 0) return;
196	    // 严格同步当前扫描结果，防止移除固件重扫后残留旧 SHA-256。
197	    scanned_mc_sha256_ = st.mc.valid ? st.mc.sha256 : std::string();
198	    scanned_th_sha256_ = st.th.valid ? st.th.sha256 : std::string();
199	    const std::string phase_str = format_ota_phase(st);
200	    const std::string mc_str = format_ota_pkg("fw_mc.bin", st.mc);
201	    const std::string th_str = format_ota_pkg("fw_th.bin", st.th);
202	    lv_subject_copy_string(&phase_subject_, phase_str.c_str());
203	    lv_subject_copy_string(&mc_pkg_subject_, mc_str.c_str());
204	    lv_subject_copy_string(&th_pkg_subject_, th_str.c_str());
205	    lv_subject_set_int(&progress_subject_, static_cast<int32_t>(st.progress_pct));
206	    if (scan_feedback_pending_) {
207	        // 仅当 last_rpc_code==0 且 phase==READY 时弹成功提示，RPC 失败或包异常一律弹告警/错误。
208	        const bool rpc_failed = (st.last_rpc_code < 0);
209	        const bool scan_done = (st.last_rpc_code == 0) && (!st.active) &&
210	                               (st.phase == "READY" || st.phase == "FAILED");
211	        if (rpc_failed || scan_done) {
212	            scan_feedback_pending_ = false;
213	            ToastSeverity sev = ToastSeverity::WARNING;
214	            if (!rpc_failed && st.phase == "READY") sev = ToastSeverity::SUCCESS;
215	            else if (rpc_failed && st.error == "RPC_DISCONNECTED") sev = ToastSeverity::ERROR;
216	            ToastManager::instance().show(sev, phase_str.c_str(), 2800);
217	        }
218	    }
219	    const bool busy = (snap.last_estop_outcome == helix::aisoc::AisocEstopOutcome::BACKEND_BUSY) ||
220	                      (st.last_rpc_code == -5) || st.active;
221	    if (busy) {
222	        set_lock_hint("状态: 后台已锁定 (BUSY)");
223	    } else if (snap.estop_latched) {
224	        set_lock_hint("状态: 设备已确认急停");
225	    } else if (!snap.dm_connected) {
226	        set_lock_hint("状态: 本地服务未连接（请检查后台服务后重试）");
227	    } else if (st.maintenance || snap.mc.is_boot_mode) {
228	        set_lock_hint("状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC");
229	    } else if (!snap.mc.online || !snap.th.online) {
230	        set_lock_hint("状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）");
231	    } else {
232	        set_lock_hint("状态: 就绪");
233	    }
234	#endif
235	}
