237	void OtaLocalOverlay::handle_scan() {
238	#ifdef HELIX_ENABLE_AISOC
239	    auto* conn = helix::aisoc::active_aisoc_connection();
240	    const auto st = conn ? conn->ota_status() : helix::aisoc::AisocOtaStatus{};
241	    const auto verdict = helix::aisoc::check_ota_scan_gate(conn != nullptr, st);
242	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
243	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
244	        return;
245	    }
246	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
247	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
248	        return;
249	    }
250	    scan_feedback_pending_ = true;
251	    helix::aisoc::AisocOtaRequest req;
252	    req.operation = 0U;
253	    req.target_mask = 3U;
254	    conn->request_ota(req);
255	#endif
256	}
