258	void OtaLocalOverlay::handle_start_upgrade() {
259	#ifdef HELIX_ENABLE_AISOC
260	    auto* conn = helix::aisoc::active_aisoc_connection();
261	    if (!conn) {
262	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
263	        return;
264	    }
265	    const uint8_t mask = static_cast<uint8_t>((select_mc_ ? 1U : 0U) | (select_th_ ? 2U : 0U));
266	    const auto st = conn->ota_status();
267	    const auto snap = conn->snapshot();
268	    const auto verdict = helix::aisoc::check_ota_upgrade_gate(mask, confirmed_safe_, st, snap);
269	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MISSING_SELECTION) {
270	        ToastManager::instance().show(ToastSeverity::WARNING, "请选择升级节点并开启安全前置确认", 2500);
271	        return;
272	    }
273	    if (verdict == helix::aisoc::AisocOtaGateVerdict::BACKEND_BUSY) {
274	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
275	        return;
276	    }
277	    if (verdict == helix::aisoc::AisocOtaGateVerdict::MC_RECOVERY_ONLY) {
278	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: MC 处于待恢复模式，请取消选择 TH 仅升级 MC", 2800);
279	        return;
280	    }
281	    if (verdict == helix::aisoc::AisocOtaGateVerdict::PACKAGE_NOT_READY) {
282	        ToastManager::instance().show(ToastSeverity::WARNING, "请先扫描固件并确认所选节点固件包校验通过", 2500);
283	        return;
284	    }
285	    if (verdict == helix::aisoc::AisocOtaGateVerdict::DISCONNECTED) {
286	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
287	        return;
288	    }
289	    if (verdict == helix::aisoc::AisocOtaGateVerdict::NODE_OFFLINE) {
290	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）", 2500);
291	        return;
292	    }
293	    scan_feedback_pending_ = false;
294	    helix::aisoc::AisocOtaRequest req;
295	    req.operation = 1U;
296	    req.target_mask = mask;
297	    req.confirmed_safe = true;
298	    req.allow_reflash = allow_reflash_;
299	    req.mc_sha256 = ((mask & 1U) != 0U) ? st.mc.sha256 : std::string();
300	    req.th_sha256 = ((mask & 2U) != 0U) ? st.th.sha256 : std::string();
301	    conn->request_ota(req);
302	#endif
303	}
