341	bool parse_dm_snapshot_json(const std::string& json, AisocSnapshot* out_snap) {
342	    if (out_snap == nullptr || !detail::json_is_valid_object(json)) return false;
343	    std::string sys_st, dev_st;
344	    if (!detail::json_extract_string(json, "system_status", &sys_st)) return false;
345	    if (!detail::json_extract_string(json, "device_state", &dev_st)) return false;
346	    out_snap->system_status = sys_st;
347	    out_snap->device_state = dev_st;
348	    out_snap->maintenance_locked = (sys_st == "MAINTENANCE_HOLD");
349	    // 以权威 GetSnapshot 的 system_status 驱动急停锁存态，确保外部解除后自动同步清除。
350	    out_snap->estop_latched = (sys_st == "EMERGENCY_STOP_INVOKED");
351	    std::string devices_obj;
352	    if (detail::json_extract_object(json, "devices", &devices_obj)) {
353	        std::string mc_obj, th_obj;
354	        if (detail::json_extract_object(devices_obj, "mc", &mc_obj)) parse_single_mcu(mc_obj, &out_snap->mc);
355	        if (detail::json_extract_object(devices_obj, "th", &th_obj)) parse_single_mcu(th_obj, &out_snap->th);
356	    }
357	    return true;
358	}
