363	    if (!detail::json_extract_string(json, "phase", &st.phase)) return false;
364	    detail::json_extract_string(json, "policy", &st.policy);
365	    detail::json_extract_string(json, "task_id", &st.task_id);
366	    detail::json_extract_u64(json, "event_id", &st.event_id);
367	    detail::json_extract_bool(json, "active", &st.active);
368	    detail::json_extract_bool(json, "maintenance", &st.maintenance);
369	    uint64_t v = 0U;
370	    if (detail::json_extract_u64(json, "target_mask", &v)) st.target_mask = static_cast<uint32_t>(v);
371	    if (detail::json_extract_u64(json, "active_node", &v)) st.active_node = static_cast<uint32_t>(v);
372	    if (detail::json_extract_u64(json, "progress_pct", &v)) st.progress_pct = static_cast<uint32_t>(v);
373	    detail::json_extract_string(json, "error", &st.error);
