410	void AisocConnection::stop() {
411	    std::thread to_join;
412	    {
413	        std::lock_guard<std::mutex> lock(mutex_);
414	        if (!running_ && !worker_.joinable()) {
415	            close_dds_ota(&dds_part_, &dds_ota_sub_);
416	            close_dbus(&dbus_handle_);
417	            return;
418	        }
419	        stop_requested_ = true;
420	        cv_.notify_all();
421	        to_join = std::move(worker_);
422	    }
423	    if (to_join.joinable()) to_join.join();
424	    std::lock_guard<std::mutex> lock(mutex_);
425	    running_ = false;
426	    close_dds_ota(&dds_part_, &dds_ota_sub_);
427	    close_dbus(&dbus_handle_);
