480	void AisocConnection::worker_loop() {
481	    while (true) {
482	        process_pending_estops();
483	        process_pending_ota();
484	        poll_ota_dds();
485	        bool do_refresh = false;
486	        {
487	            std::lock_guard<std::mutex> lock(mutex_);
488	            if (stop_requested_) break;
489	            do_refresh = refresh_requested_;
490	            refresh_requested_ = false;
491	        }
492	        poll_once();
493	        poll_ota_dds();
494	        if (do_refresh) process_pending_estops();
495	        std::unique_lock<std::mutex> lock(mutex_);
496	        if (stop_requested_) break;
497	        uint32_t wait_ms = config_.poll_interval_ms > 0U ? config_.poll_interval_ms : 1000U;
498	        if ((ota_status_.active || pending_reboot_verify_) && wait_ms > 80U) wait_ms = 80U;
499	        cv_.wait_for(lock, std::chrono::milliseconds(wait_ms), [this]() {
500	            return stop_requested_ || refresh_requested_ || !estop_queue_.empty() || !ota_queue_.empty();
501	        });
502	        if (stop_requested_) break;
503	    }
504	}
505	
506	void AisocConnection::process_pending_estops() {
507	    while (true) {
508	        bool engage = true;
509	        EstopCallback cb;
510	        {
511	            std::lock_guard<std::mutex> lock(mutex_);
512	            if (stop_requested_ || estop_queue_.empty()) return;
513	            engage = estop_queue_.front();
514	            estop_queue_.erase(estop_queue_.begin());
515	            cb = estop_cb_;
516	        }
517	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
518	        const AisocEstopResult res = execute_dm_estop(conn, engage, config_.rpc_timeout_ms);
519	        if (res.outcome == AisocEstopOutcome::DISCONNECTED) close_dbus(&dbus_handle_);
520	        AisocSnapshot updated;
521	        AisocOtaStatus ota_snap;
522	        OtaStatusCallback ota_cb;
523	        {
524	            std::lock_guard<std::mutex> lock(mutex_);
525	            if (res.outcome == AisocEstopOutcome::CONFIRMED) snapshot_.estop_latched = engage;
526	            snapshot_.last_estop_outcome = res.outcome;
527	            snapshot_.last_estop_detail = res.detail;
528	            updated = snapshot_;
529	            ota_snap = ota_status_;
530	            ota_cb = ota_cb_;
531	        }
532	        publish_if_changed(updated, true);
533	        if (ota_cb) ota_cb(ota_snap);
534	        if (cb) cb(res);
535	    }
536	}
537	
538	void AisocConnection::process_pending_ota() {
539	    while (true) {
540	        AisocOtaRequest req;
541	        {
542	            std::lock_guard<std::mutex> lock(mutex_);
543	            if (stop_requested_ || ota_queue_.empty()) return;
544	            req = ota_queue_.front();
545	            ota_queue_.erase(ota_queue_.begin());
546	        }
547	        ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
548	        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
549	        uint64_t task_id = 0U;
550	        const int32_t rc = execute_fwd_ota_command(conn, req, config_.rpc_timeout_ms, &task_id);
551	        AisocOtaStatus next;
552	        {
553	            std::lock_guard<std::mutex> lock(mutex_);
554	            next = ota_status_;
555	            next.last_rpc_code = rc;
556	            if (rc == 0) {
557	                tracked_task_id_ = std::to_string(task_id);
558	                pending_reboot_verify_ = false;
559	                next.task_id = tracked_task_id_;
560	                next.event_id = 0U;
561	                next.reboot_verified = false;
562	                next.error.clear();
563	            } else {
564	                pending_reboot_verify_ = false;
565	                next.active = false;
566	                next.reboot_verified = false;
567	                if (req.operation == 0U) {
568	                    // 重扫请求被拒或断连时立即作废旧 READY 状态与包摘要，严禁残留旧校验结果。
569	                    next.phase = "FAILED";
570	                    next.mc = AisocOtaNodeInfo{};
571	                    next.th = AisocOtaNodeInfo{};
572	                }
573	                if (rc == -5) {
574	                    next.error = "BACKEND_BUSY";
575	                } else if (conn == nullptr || rc == -100 || rc == AISOC_DBUS_ERR_DISCONNECTED || rc == -1) {
576	                    next.phase = "FAILED";
577	                    next.error = "RPC_DISCONNECTED";
578	                } else {
579	                    next.phase = "FAILED";
580	                    next.error = "OTA_COMMAND_REJECTED";
581	                }
582	            }
583	        }
584	        emit_ota_status(next);
585	    }
586	}
587	
588	void AisocConnection::poll_ota_dds() {
589	    auto* sub = ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
590	    if (sub == nullptr) return;
591	    aisoc_ota_status_t sample = {};
592	    for (uint32_t i = 0U; i < 32U; ++i) {
593	        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
594	        AisocOtaStatus parsed;
595	        if (!parse_ota_status_json(sample.json, &parsed)) continue;
596	        bool accept = false;
597	        {
598	            std::lock_guard<std::mutex> lock(mutex_);
599	            const bool task_ok = tracked_task_id_.empty() || parsed.task_id == tracked_task_id_;
600	            const bool mono_ok = (parsed.task_id != ota_status_.task_id) ||
601	                                 (parsed.event_id > ota_status_.event_id);
602	            if (task_ok && mono_ok) {
603	                accept = true;
604	                // 收到真实 DDS 新快照时清零历史 RPC 负码，防止旧错误码污染当前任务状态。
605	                parsed.last_rpc_code = 0;
606	                parsed.reboot_verified = false;
607	                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
608	            }
609	        }
610	        if (accept) emit_ota_status(parsed);
611	    }
612	}
