614	void AisocConnection::verify_pending_ota_reboot(const McuNodeInfo& dm_mc, const McuNodeInfo& dm_th) {
615	    AisocOtaStatus verified;
616	    bool newly_verified = false;
617	    {
618	        std::lock_guard<std::mutex> lock(mutex_);
619	        if (!pending_reboot_verify_ || ota_status_.phase != "SUCCEEDED") return;
620	        const uint32_t mask = ota_status_.target_mask;
621	        if (mask == 0U) return;
622	        const bool mc_ok = ((mask & 1U) == 0U) || node_reboot_verified(dm_mc, ota_status_.mc.pre_boot_id);
623	        const bool th_ok = ((mask & 2U) == 0U) || node_reboot_verified(dm_th, ota_status_.th.pre_boot_id);
624	        if (mc_ok && th_ok) {
625	            pending_reboot_verify_ = false;
626	            ota_status_.reboot_verified = true;
627	            verified = ota_status_;
628	            newly_verified = true;
629	        }
630	    }
631	    if (newly_verified) emit_ota_status(verified);
632	}
