634	void AisocConnection::poll_once() {
635	    AisocSnapshot next;
636	    {
637	        std::lock_guard<std::mutex> lock(mutex_);
638	        next.ap = snapshot_.ap;
639	        next.estop_latched = snapshot_.estop_latched;
640	        next.last_estop_outcome = snapshot_.last_estop_outcome;
641	        next.last_estop_detail = snapshot_.last_estop_detail;
642	    }
643	    auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
644	    if (conn == nullptr) {
645	        next.estop_latched = false;
646	        next.device_state = "OFFLINE";
647	        next.system_status = "OFFLINE";
648	        publish_if_changed(next, false);
649	        return;
650	    }
651	    std::string ver_json;
652	    const aisoc_dbus_status_t ver_st = call_dm_string(conn, "GetVersionInfo", config_.rpc_timeout_ms, &ver_json);
653	    if (ver_st != AISOC_DBUS_OK || !parse_dm_version_json(ver_json, &next.mc, &next.th)) {
654	        if (ver_st == AISOC_DBUS_ERR_DISCONNECTED) close_dbus(&dbus_handle_);
655	        next.dm_connected = false;
656	        next.estop_latched = false;
657	        next.device_state = "OFFLINE";
658	        next.system_status = "OFFLINE";
659	        publish_if_changed(next, false);
660	        return;
661	    }
662	    next.dm_connected = true;
663	    verify_pending_ota_reboot(next.mc, next.th);
664	    std::string snap_json, state_json;
665	    if (call_dm_string(conn, "GetSnapshot", config_.rpc_timeout_ms, &snap_json) == AISOC_DBUS_OK) {
666	        parse_dm_snapshot_json(snap_json, &next);
667	    }
668	    if (call_dm_string(conn, "GetDeviceState", config_.rpc_timeout_ms, &state_json) == AISOC_DBUS_OK) {
669	        std::string state_str;
670	        if (detail::json_extract_string(state_json, "state", &state_str)) next.device_state = state_str;
671	    }
672	    if (!next.mc.online) {
673	        McuNodeInfo fwd_mc;
674	        if (query_forward_version(conn, 1U, config_.rpc_timeout_ms, &fwd_mc)) next.mc = fwd_mc;
675	    }
676	    publish_if_changed(next, false);
677	}
