679	void AisocConnection::publish_if_changed(const AisocSnapshot& next_snap, bool force_emit) {
680	    SnapshotCallback cb;
681	    OtaStatusCallback ota_cb;
682	    AisocOtaStatus ota_snap;
683	    {
684	        std::lock_guard<std::mutex> lock(mutex_);
685	        if (!force_emit && snapshot_equal(snapshot_, next_snap)) return;
686	        snapshot_ = next_snap;
687	        cb = snapshot_cb_;
688	        ota_cb = ota_cb_;
689	        ota_snap = ota_status_;
690	    }
691	    if (cb) cb(next_snap);
692	    // 设备连接或节点在线态变化时同步唤醒已打开的 OTA 页面刷新离线/就绪提示。
693	    if (ota_cb && !force_emit) ota_cb(ota_snap);
694	}
