716	AisocOtaGateVerdict check_ota_scan_gate(bool has_conn, const AisocOtaStatus& st) {
717	    if (!has_conn) return AisocOtaGateVerdict::DISCONNECTED;
718	    // 仅拦截在途活跃任务；MC 待恢复模式 (!st.active && st.maintenance) 必须允许扫描恢复包。
719	    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
720	    return AisocOtaGateVerdict::ALLOW;
721	}
722	
723	AisocOtaGateVerdict check_ota_upgrade_gate(uint8_t mask, bool confirmed_safe,
724	                                           const AisocOtaStatus& st, const AisocSnapshot& snap) {
725	    if (mask == 0U || !confirmed_safe) return AisocOtaGateVerdict::MISSING_SELECTION;
726	    if (st.active) return AisocOtaGateVerdict::BACKEND_BUSY;
727	    const bool mc_recovery = (!st.active) && (st.maintenance || snap.mc.is_boot_mode ||
728	                                              st.error == "RESTORE_MC_BEFORE_TH");
729	    if (mc_recovery && mask != 1U) return AisocOtaGateVerdict::MC_RECOVERY_ONLY;
730	    const bool mc_ready = ((mask & 1U) == 0U) || (st.mc.valid && !st.mc.sha256.empty());
731	    const bool th_ready = ((mask & 2U) == 0U) || (st.th.valid && !st.th.sha256.empty());
732	    if (!mc_ready || !th_ready) return AisocOtaGateVerdict::PACKAGE_NOT_READY;
733	    if (!snap.dm_connected) return AisocOtaGateVerdict::DISCONNECTED;
734	    // MC 待恢复单选升级允许通过串口直接刷回 App，不因 DM 暂报 MC 离线阻断恢复。
735	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online || mc_recovery;
736	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
737	    if (!mc_online || !th_online) return AisocOtaGateVerdict::NODE_OFFLINE;
738	    return AisocOtaGateVerdict::ALLOW;
739	}
