/**
 * @brief 一键搭建 DeviceManager 集成测试所需的 D-Bus、DDS 与服务实例环境
 */
static bool setup_dev_test_env(DevTestEnv* env) {
    if (env == nullptr) return false;
    env->d_pid = spawn_dbus_daemon(env->bus_addr, sizeof(env->bus_addr));
    if (env->d_pid <= 0) return false;

    init_mock_forward(&env->mock_fwd_conn, env->bus_addr);
    env->fwd_thread = std::thread([env]() {
        while (env->fwd_thread_run.load()) {
            bool disp = false;
            aisoc_dbus_dispatch_once(&env->mock_fwd_conn, 10, &disp);
        }
    });

    device_manager_config_t cfg = {};
    cfg.dbus_bus_type = AISOC_DBUS_BUS_CUSTOM;
    cfg.dbus_custom_address = env->bus_addr;
    cfg.initial_generation_id = 10U;
    device_manager_init(&cfg, &env->dev_state);
    if (device_manager_start(&env->dev_state) != AISOC_DEV_OK) return false;

    env->dev_thread = std::thread([env]() {
        while (env->dev_thread_run.load()) {
            bool disp = false;
            device_manager_dispatch(&env->dev_state, 10, &disp);
        }
    });

    setup_test_dds_and_dbus_cli(env);
    usleep(100000);
    return true;
}

/**
 * @brief 停止 DeviceManager 测试环境并清理 DDS 实体与 dbus-daemon 子进程
 */
static void teardown_dev_test_env(DevTestEnv* env) {
    env->dev_thread_run.store(false);
    if (env->dev_thread.joinable()) env->dev_thread.join();
    env->fwd_thread_run.store(false);
    if (env->fwd_thread.joinable()) env->fwd_thread.join();

    aisoc_dbus_conn_close(&env->cli_conn);
    aisoc_dds_subscriber_destroy(env->test_snap_sub);
    aisoc_dds_publisher_destroy(env->test_raw_pub);
    aisoc_dds_participant_destroy(env->test_part);

    device_manager_stop(&env->dev_state);
    aisoc_dbus_conn_close(&env->mock_fwd_conn);

    kill(env->d_pid, SIGTERM);
    waitpid(env->d_pid, nullptr, 0);
}

