/** @brief state为业务主线程拥有的服务；每500ms轮转一个节点，失败只读探测不合成身份。 */
static void refresh_identity(device_manager_state_t* state) {
    if (state == nullptr) return;
    const uint64_t now = get_host_monotonic_ns();
    pthread_mutex_lock(&state->state_mutex);
    const bool due = !state->is_maintenance && now >= state->next_identity_probe_ns;
    const uint8_t node = state->next_identity_node == 2U ? 2U : 1U;
    if (due) {
        state->next_identity_probe_ns = now + 500000000ULL;
        state->next_identity_node = node == 1U ? 2U : 1U;
    }
    pthread_mutex_unlock(&state->state_mutex);
    if (due) device_manager_sync_mcu_version(state, node);
}

