/** @brief 调用 ForwardInterface.OtaCommand 发起固定目录扫描或升级。 */
int32_t execute_fwd_ota_command(aisoc_dbus_conn_t* conn, const AisocOtaRequest& req_data,
                                int32_t timeout_ms, uint64_t* out_task_id) {
    if (conn == nullptr || out_task_id == nullptr) return -100;
    const aisoc_dbus_method_call_t call = {
        AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "OtaCommand"};
    aisoc_dbus_msg_t req = {}, reply = {};
    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) return -100;
    aisoc_dbus_msg_append_byte(&req, req_data.operation);
    aisoc_dbus_msg_append_byte(&req, req_data.target_mask);
    aisoc_dbus_msg_append_bool(&req, req_data.confirmed_safe);
    aisoc_dbus_msg_append_bool(&req, req_data.allow_reflash);
    aisoc_dbus_msg_append_string(&req, req_data.mc_sha256.c_str());
    aisoc_dbus_msg_append_string(&req, req_data.th_sha256.c_str());
    const aisoc_dbus_call_opts_t opts = {timeout_ms > 1000 ? timeout_ms : 1000, true};
    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
    aisoc_dbus_msg_unref(&req);
    if (st != AISOC_DBUS_OK) {
        if (st == AISOC_DBUS_ERR_DISCONNECTED || st == AISOC_DBUS_ERR_INTERNAL || st == AISOC_DBUS_ERR_NO_REPLY) {
            return -100;
        }
        return static_cast<int32_t>(st);
    }
    aisoc_dbus_iter_t it = {};
    aisoc_dbus_iter_init(&reply, &it);
    int32_t err_code = -1;
    uint64_t task_id = 0U;
    const bool ok = aisoc_dbus_iter_get_int32(&it, &err_code) == AISOC_DBUS_OK &&
                    aisoc_dbus_iter_get_uint64(&it, &task_id) == AISOC_DBUS_OK;
    aisoc_dbus_msg_unref(&reply);
    if (!ok) return -1;
    *out_task_id = task_id;
    return err_code;
}

