aisoc_dev_status_t device_manager_sync_mcu_version(
    device_manager_state_t* state,
    uint8_t target_node
) {
    if (state == nullptr) {
        return AISOC_DEV_ERR_NULL_PTR;
    }
    if (target_node != 1U && target_node != 2U) {
        return AISOC_DEV_ERR_INVALID_ARG;
    }
    aisoc_dev_mcu_version_t ver;
    std::memset(&ver, 0, sizeof(ver));
    const aisoc_dev_status_t st = query_forward_version_rpc(state, target_node, &ver);
    const char* node_str = (target_node == 1U) ? "MC" : "TH";
    const uint64_t now_ns = get_host_monotonic_ns();

    pthread_mutex_lock(&state->state_mutex);
    aisoc_dev_status_t upd_st = st;
    if (st == AISOC_DEV_OK) upd_st = dev_state_update_mcu_version(state, node_str, &ver, now_ns);
    else if (st != AISOC_DEV_ERR_BUSY) dev_state_record_mcu_query_failed(state, node_str, now_ns);
    pthread_mutex_unlock(&state->state_mutex);
    return upd_st;
}

/**
 * @brief 初始化 MC 与 TH 节点的默认离线版本槽
 * @param state 设备管理服务状态结构体指针
 */
static void init_default_mcu_versions(device_manager_state_t* state) {
    if (state == nullptr) {
        return;
    }
    aisoc_dev_mcu_version_t mc_ver;
    mc_ver = {};
    mc_ver.is_valid = false;
    mc_ver.status = DEV_VER_STATUS_OFFLINE;

